input.contents:
/**
 * 智能体运营 v1.1 专项检查：页面存在、脚本可加载、筛选/发布/审核/上架链路可运行。
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { JSDOM } = require('jsdom');

const root = path.join(__dirname, '..');
const v11 = path.join(root, '智能体运营v1.1');
const pages = ['index.html', 'dashboard.html', 'audit-workbench.html', 'audit-review.html', 'agent-detail.html'];
let fail = 0;

function pass(name) {
  console.log('PASS:', name);
}

function failCheck(name, detail) {
  fail++;
  console.error('FAIL:', name, detail || '');
}

function assert(cond, name, detail) {
  if (cond) pass(name);
  else failCheck(name, detail);
}

const sharedStorage = {};

function loadPage(page, query, extraScripts) {
  const html = fs.readFileSync(path.join(v11, page), 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/智能体运营v1.1/' + page + (query || ''),
    runScripts: 'outside-only',
    pretendToBeVisual: true
  });
  dom.window.sessionStorage.getItem = function (key) {
    return Object.prototype.hasOwnProperty.call(sharedStorage, key) ? sharedStorage[key] : null;
  };
  dom.window.sessionStorage.setItem = function (key, value) {
    sharedStorage[key] = String(value);
  };
  dom.window.sessionStorage.removeItem = function (key) {
    delete sharedStorage[key];
  };
  dom.window.confirm = function () { return true; };
  const context = dom.getInternalVMContext();
  vm.runInContext(fs.readFileSync(path.join(root, 'assets', 'proto.js'), 'utf8'), context, { filename: 'proto.js' });
  vm.runInContext(fs.readFileSync(path.join(root, 'assets', 'ops-platform-shell.js'), 'utf8'), context, { filename: 'ops-platform-shell.js' });
  (extraScripts || []).forEach(function (script) {
    vm.runInContext(fs.readFileSync(script, 'utf8'), context, { filename: path.basename(script) });
  });
  vm.runInContext(fs.readFileSync(path.join(v11, 'app.js'), 'utf8'), context, { filename: 'v11-app.js' });
  if (dom.window.OpsV11 && dom.window.document.getElementById('pageMain') && !dom.window.document.getElementById('pageContent')) {
    dom.window.OpsV11.init();
  }
  return dom;
}

console.log('=== v1.1 ops check ===\n');

pages.forEach(function (page) {
  const file = path.join(v11, page);
  assert(fs.existsSync(file), page + ' exists');
  const html = fs.readFileSync(file, 'utf8');
  assert(html.includes('style.css') && html.includes('app.js') && html.includes('../assets/proto.js'), page + ' assets linked');
  assert(html.includes('ops-platform-shell.js'), page + ' uses ops shell');
});

assert(fs.existsSync(path.join(v11, 'styles.css')), 'styles.css exists');
assert(fs.existsSync(path.join(v11, 'app.js')), 'app.js exists');

const indexDom = loadPage('index.html');
const doc = indexDom.window.document;
assert(!doc.querySelector('.kpi-grid'), '主页无 KPI 四卡片');
assert(doc.querySelector('.sidebar-nav-group'), '侧栏智能体运营含下拉子菜单');
assert(!doc.querySelector('.sidebar a[href*="08-audit-queue"]'), '侧栏无独立审核工作台入口');
assert(doc.querySelectorAll('.agent-card').length >= 8, '主页渲染卡片 >= 8');
assert(doc.querySelector('.agent-card .tag-listed, .agent-card .tag-dev, .agent-card .tag-pending'), '卡片展示状态标签');
assert(doc.querySelector('[data-filter-select="type"]'), '主页类型下拉存在');
assert(doc.querySelector('[data-filter-select="status"]'), '主页状态下拉存在');
assert(doc.querySelector('[data-open-create]'), '主页含新建按钮');

const devCard = doc.querySelector('.agent-card[data-agent-status="dev"]');
assert(devCard, '存在开发中卡片');
const devMenuBtn = devCard.querySelector('[data-card-menu]');
devMenuBtn.click();
const devMenu = doc.getElementById('v11CardMenu');
assert(devMenu && devMenu.textContent.includes('发布候选版本'), '开发中菜单含发布候选版本');
assert(devMenu && devMenu.textContent.includes('开发配置'), '开发中菜单含开发配置');
assert(devMenu && !devMenu.textContent.includes('下架'), '开发中菜单不含下架');

const listedDom = loadPage('index.html');
const listedDoc = listedDom.window.document;
const listedSelect = listedDoc.querySelector('[data-filter-select="status"]');
listedSelect.value = 'listed';
listedSelect.dispatchEvent(new listedDom.window.Event('change', { bubbles: true }));
const listedCard = listedDoc.querySelector('.agent-card[data-agent-status="listed"]');
assert(listedCard, '已上架状态筛选可用');
listedCard.querySelector('[data-card-menu]').click();
const listedMenu = listedDoc.getElementById('v11CardMenu');
assert(listedMenu && listedMenu.textContent.includes('下架'), '已上架菜单含下架');
assert(listedMenu && listedMenu.textContent.includes('用户对话页'), '已上架菜单含用户对话页');

const detailDom = loadPage('agent-detail.html', '?id=agt_daily');
const detailDoc = detailDom.window.document;
assert(detailDoc.body.textContent.includes('发布候选版本'), '详情页展示发布候选版本操作');
detailDoc.querySelector('[data-publish="agt_daily"]').click();
detailDoc.getElementById('modalReleaseNote').value = '补充日报模板和审核说明';
detailDoc.querySelector('[data-modal-confirm]').click();
const daily = detailDom.window.OpsV11.getAgent('agt_daily');
assert(daily.status === 'published_pending_review', '发布后进入已发布待审核');

const auditDom = loadPage('audit-workbench.html');
const auditDoc = auditDom.window.document;
assert(auditDoc.body.textContent.includes('去审核'), '审核工作台展示去审核链接');
assert(auditDoc.querySelector('a[href*="audit-review.html"]'), '审核列表链接到审核详情');

const reviewDom = loadPage('audit-review.html', '?id=agt_analytics');
const reviewDoc = reviewDom.window.document;
assert(reviewDoc.body.textContent.includes('审核通过'), '审核详情展示审核通过按钮');
reviewDoc.querySelector('[data-approve-review]').click();
const analytics = reviewDom.window.OpsV11.getAgent('agt_analytics');
assert(analytics.status === 'approved_pending_listing', '审核详情通过后进入待上架');

const dashDom = loadPage('dashboard.html', '', [path.join(root, 'assets', 'ops-list-dashboard.js')]);
const dashDoc = dashDom.window.document;
assert(dashDoc.getElementById('opsDashKpis'), '仪表盘渲染运营 KPI');
assert(dashDoc.getElementById('opsDashCompliance'), '仪表盘渲染合规监控');
assert(!dashDoc.querySelector('#opsDashQuickLinks a[href*="audit"]'), '仪表盘无审核工作台快捷入口');
assert(!dashDoc.querySelector('[data-open-create]'), '仪表盘无新建按钮');

console.log('');
if (fail) {
  console.error('V11 OPS CHECK FAILED (' + fail + ' issue(s))');
  process.exit(1);
}
console.log('V11 OPS CHECK PASSED');

