function cardMenuItems(item) {
  var status = item.status;
  var items = [];
  if (status === 'dev') {
    items.push({ label: '发布候选版本', action: 'publish' });
    items.push({ label: '开发配置', action: 'dev' });
    items.push({ divider: true });
    items.push({ label: '删除', action: 'delete', danger: true });
  } else if (status === 'rejected') {
    items.push({ label: '查看驳回原因', action: 'detail' });
    items.push({ label: '重新发布', action: 'publish' });
    items.push({ divider: true });
    items.push({ label: '删除', action: 'delete', danger: true });
  } else if (status === 'offline') {
    items.push({ label: '重新发布', action: 'publish' });
    items.push({ label: '查看详情', action: 'detail' });
    items.push({ divider: true });
    items.push({ label: '删除', action: 'delete', danger: true });
  } else if (status === 'published_pending_review' || status === 'reviewing') {
    items.push({ label: '去审核', action: 'audit' });
    items.push({ label: '撤回发布', action: 'withdraw' });
    items.push({ label: '查看详情', action: 'detail' });
  } else if (status === 'approved_pending_listing') {
    items.push({ label: '上架', action: 'list' });
    items.push({ label: '查看详情', action: 'detail' });
  } else if (status === 'listed') {
    items.push({ label: '下架', action: 'offline' });
    items.push({ label: '用户对话页', action: 'chat' });
    items.push({ label: '查看详情', action: 'detail' });
  } else {
    items.push({ label: '查看详情', action: 'detail' });
  }
  return items;
}

