  '</article>';
}

/** 与 v1.0 列表操作一致：仅 发布/停用/上架/下架/删除；查看=点卡片；审核仅在工作台 */
function cardMenuItems(item) {
  var status = item.status;
  var items = [];
  if (status === 'dev' || status === 'rejected' || status === 'offline') {
    items.push({ label: '发布', action: 'publish' });
    items.push({ divider: true });
    items.push({ label: '删除', action: 'delete', danger: true });
  } else if (status === 'approved_pending_listing') {
    items.push({ label: '上架', action: 'list' });
  } else if (status === 'listed') {
    items.push({ label: '停用', action: 'disable' });
    items.push({ label: '下架', action: 'offline', danger: true });
  } else if (status === 'disabled') {
    items.push({ label: '启用', action: 'enable' });
    items.push({ label: '下架', action: 'offline', danger: true });
  }
  return items;
}

