assert(doc.querySelector('.sidebar-nav-group'), '侧栏智能体运营含子菜单');
const dashLink = doc.querySelector('.sidebar-subnav .sidebar-sub');
assert(dashLink && dashLink.getAttribute('href').indexOf('dashboard.html') >= 0, '子菜单仪表盘为相对路径');
assert(dashLink.getAttribute('href').indexOf('智能体运营v1.1/') < 0, 'v1.1 内导航不含重复目录前缀');

const devCard = doc.querySelector('.agent-card[data-agent-status="dev"]');
devCard.querySelector('[data-card-menu]').click();
const devMenu = doc.getElementById('v11CardMenu');
assert(devMenu && devMenu.textContent.includes('发布'), '开发中菜单仅含发布');
assert(devMenu && !devMenu.textContent.includes('查看'), '菜单不含查看');
assert(devMenu && !devMenu.textContent.includes('审核'), '菜单不含审核');

const reviewCard = doc.querySelector('.agent-card[data-agent-status="reviewing"]');
assert(reviewCard && !reviewCard.querySelector('[data-card-menu]'), '审核中卡片无操作菜单');

const listedDom = loadPage('index.html');
const listedDoc = listedDom.window.document;
const listedCard = listedDoc.querySelector('.agent-card[data-agent-status="listed"]');
listedCard.querySelector('[data-card-menu]').click();
const listedMenu = listedDoc.getElementById('v11CardMenu');
assert(listedMenu && listedMenu.textContent.includes('停用'), '已上架菜单含停用');
assert(listedMenu && listedMenu.textContent.includes('下架'), '已上架菜单含下架');

const dashDom = loadPage('dashboard.html', '', [path.join(root, 'assets', 'ops-list-dashboard.js')]);
assert(dashDom.window.document.getElementById('opsDashKpis'), '仪表盘可渲染');
const auditDom = loadPage('audit-workbench.html');
assert(auditDom.window.document.body.textContent.includes('去审核'), '审核工作台可渲染');

console.log('');
if (fail) {
  console.error('V11 OPS CHECK FAILED (' + fail + ' issue(s))');
  process.exit(1);
}
console.log('V11 OPS CHECK PASSED');
